export const chartTypes=[{key:'position',name:'각도',unit:'°',color:'#a5a0ff'},{key:'speed',name:'회전 속도',unit:'ERPM',color:'#63bcf7'},{key:'amps',name:'전류',unit:'A',color:'#55d4b2'},{key:'temp',name:'온도',unit:'°C',color:'#efbc78'}];
const NS='http://www.w3.org/2000/svg';
const windows=Object.fromEntries(chartTypes.map(t=>[t.key,30]));
function node(tag,attrs){const el=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));return el;}
export function setupCharts(onFullscreen){const host=document.getElementById('charts'),options=document.getElementById('chart-options');for(const type of chartTypes){const label=document.createElement('label');const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.dataset.chart=type.key;checkbox.checked=true;label.append(checkbox,document.createTextNode(type.name));options.append(label);const card=document.createElement('section');card.className='chart-card';card.id=`chart-${type.key}`;card.innerHTML=`<div class="chart-title"><strong>${type.name}</strong><span>${type.unit}</span><button class="chart-reset" aria-label="${type.name} 그래프 확대 초기화" title="확대 초기화">↺</button><button class="chart-full" aria-label="${type.name} 그래프 전체 화면" title="전체 화면">⛶</button></div><div class="chart-container"><svg role="img" aria-label="${type.name} 모의 데이터 시간 그래프" viewBox="0 0 320 135" preserveAspectRatio="none"></svg><div class="chart-tooltip" hidden></div></div><div class="chart-tip">최근 30초 · 휠로 확대 · 마우스로 값 확인</div>`;host.append(card);checkbox.onchange=()=>card.hidden=!checkbox.checked;card.querySelector('.chart-full').onclick=()=>onFullscreen(card);card.querySelector('.chart-reset').onclick=()=>windows[type.key]=30;const svg=card.querySelector('svg');svg.addEventListener('wheel',event=>{event.preventDefault();windows[type.key]=Math.min(60,Math.max(3,windows[type.key]*(event.deltaY>0?1.25:.8)));},{passive:false});svg.addEventListener('pointermove',event=>{const series=card._series??[];if(!series.length)return;const rect=svg.getBoundingClientRect(),ratio=Math.min(1,Math.max(0,((event.clientX-rect.left)/rect.width*320-36)/274));const end=series.at(-1).t,time=end-windows[type.key]+ratio*windows[type.key];const sample=series.reduce((best,p)=>Math.abs(p.t-time)<Math.abs(best.t-time)?p:best);const tip=card.querySelector('.chart-tooltip');tip.hidden=false;tip.textContent=`${Math.max(0,end-sample.t).toFixed(1)}초 전 · ${Number(sample[type.key]).toFixed(1)} ${type.unit}${type.key==='position'&&sample.target!==null?' / 목표 '+sample.target.toFixed(1)+'°':''}`;});svg.addEventListener('pointerleave',()=>card.querySelector('.chart-tooltip').hidden=true);}}
export function renderCharts(motor){for(const type of chartTypes){const card=document.getElementById(`chart-${type.key}`);if(card.hidden)continue;const svg=card.querySelector('svg'),duration=windows[type.key];const series=motor.history;card._series=series;svg.replaceChildren();const end=series.at(-1)?.t??0;const data=series.filter(p=>p.t>=end-duration);let values=data.flatMap(p=>type.key==='position'?[p.position,p.target??p.position]:[p[type.key]]);if(!values.length)values=[0,1];let min=Math.min(...values),max=Math.max(...values);const padding=Math.max((max-min)*.15,type.key==='temp'?.5:type.key==='amps'?.1:1);min-=padding;max+=padding;const x=t=>36+(t-(end-duration))/duration*274,y=v=>107-(v-min)/(max-min)*94;
 for(let i=0;i<3;i++){const value=min+(max-min)*i/2;svg.append(node('line',{x1:36,x2:310,y1:y(value),y2:y(value),stroke:'#253147','stroke-width':'.8'}));const label=node('text',{x:30,y:y(value)+3,fill:'#73849e','font-size':8,'text-anchor':'end'});label.textContent=value.toFixed(1);svg.append(label);}for(let i=0;i<3;i++){const label=node('text',{x:36+i*137,y:127,fill:'#73849e','font-size':8,'text-anchor':i===0?'start':i===2?'end':'middle'});label.textContent=i===2?'현재':`−${Math.round(duration*(1-i/2))}초`;svg.append(label);}
 function line(key,color,dash){const segments=[];let active=[];for(const p of data){if(p[key]===null){if(active.length)segments.push(active);active=[];}else active.push(`${x(p.t).toFixed(2)},${y(p[key]).toFixed(2)}`);}if(active.length)segments.push(active);for(const points of segments)svg.append(node('polyline',{points:points.join(' '),fill:'none',stroke:color,'stroke-width':1.7,...(dash?{'stroke-dasharray':'4 4'}:{})}));}
 line(type.key,type.color);if(type.key==='position')line('target','#5ea4ff',true);card.querySelector('.chart-tip').textContent=`최근 ${Math.round(duration)}초 · ${type.key==='position'?'실선 현재 / 점선 전송 목표':'휠 확대 · 마우스로 값 확인'}`;}}
export function resetZoom(){for(const type of chartTypes)windows[type.key]=30;}
